// @FIGURE_CODE_BEGIN
var R_LEVEL = 0.4; // fixed reactant baseline
var state = { barrier: 0.55, product: 0.15, preset: 'a' };

function smoothstep(u){ u = Math.max(0, Math.min(1, u)); return u*u*(3-2*u); }

// Smooth rounded hump: Gaussian bump added to a sigmoid baseline
var PEAK_POS = 0.45, SIGMA = 0.11;

function curvePoint(t){
  var R = R_LEVEL, TS = state.barrier, P = state.product;
  // Baseline: smooth transition from R to P
  var base = R + (P - R) * smoothstep((t - 0.15) / 0.65);
  // Gaussian bump centered at PEAK_POS
  var g = Math.exp(-((t - PEAK_POS) * (t - PEAK_POS)) / (2 * SIGMA * SIGMA));
  // Amplitude so that curve(PEAK_POS) = TS
  var baseAtPeak = R + (P - R) * smoothstep((PEAK_POS - 0.15) / 0.65);
  var A = TS - baseAtPeak;
  return base + A * g;
}

function buildData(){
  var pts = [];
  for (var i = 0; i <= 300; i++){
    var t = i / 300;
    pts.push({ x: t, y: curvePoint(t) });
  }
  return pts;
}

function arrowHead(ctx, x, y, ang, s){
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x - s*Math.cos(ang - 0.4), y - s*Math.sin(ang - 0.4));
  ctx.lineTo(x - s*Math.cos(ang + 0.4), y - s*Math.sin(ang + 0.4));
  ctx.closePath();
  ctx.fill();
}

function dblArrow(ctx, x, y1, y2){
  ctx.beginPath(); ctx.moveTo(x, y1); ctx.lineTo(x, y2); ctx.stroke();
  var up = (y1 < y2) ? -Math.PI/2 : Math.PI/2;
  var dn = (y1 < y2) ? Math.PI/2 : -Math.PI/2;
  arrowHead(ctx, x, y1, up, 6);
  arrowHead(ctx, x, y2, dn, 6);
}

function haloText(ctx, txt, x, y, align){
  ctx.save();
  ctx.font = '600 13px sans-serif';
  ctx.textAlign = align || 'center';
  ctx.textBaseline = 'middle';
  ctx.lineWidth = 4; ctx.strokeStyle = '#ffffff'; ctx.lineJoin = 'round';
  ctx.strokeText(txt, x, y);
  ctx.fillStyle = '#111';
  ctx.fillText(txt, x, y);
  ctx.restore();
}

var annotPlugin = {
  id: 'annot',
  beforeDraw: function(chart){
    var a = chart.chartArea, ctx = chart.ctx;
    ctx.save();
    ctx.fillStyle = '#e7f3fb';
    ctx.fillRect(a.left, a.top, a.right - a.left, a.bottom - a.top);
    ctx.restore();
  },
  afterDatasetsDraw: function(chart){
    var a = chart.chartArea, ctx = chart.ctx;
    var X = chart.scales.x, Y = chart.scales.y;
    var px = function(wx){ return X.getPixelForValue(wx); };
    var py = function(wy){ return Y.getPixelForValue(wy); };
    var R = R_LEVEL, TS = state.barrier, P = state.product;
    ctx.save();

    // decorative Energy gradient up-arrow (left)
    var ex = a.left - 30;
    var grad = ctx.createLinearGradient(0, a.bottom, 0, a.top);
    grad.addColorStop(0, '#fff3c4'); grad.addColorStop(1, '#ef8a3c');
    ctx.strokeStyle = grad; ctx.fillStyle = grad; ctx.lineWidth = 12; ctx.lineCap = 'butt';
    ctx.beginPath(); ctx.moveTo(ex, a.bottom); ctx.lineTo(ex, a.top + 14); ctx.stroke();
    arrowHead(ctx, ex, a.top, -Math.PI/2, 12);
    ctx.save();
    ctx.translate(ex - 14, (a.top + a.bottom)/2); ctx.rotate(-Math.PI/2);
    ctx.font = '700 13px sans-serif'; ctx.fillStyle = '#222'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText('Energy', 0, 0); ctx.restore();

    // decorative Reaction progress magenta right-arrow (bottom)
    var ry = a.bottom + 28;
    ctx.strokeStyle = '#e01a83'; ctx.fillStyle = '#e01a83'; ctx.lineWidth = 2.5;
    ctx.beginPath(); ctx.moveTo(a.left + 40, ry); ctx.lineTo(a.right - 12, ry); ctx.stroke();
    arrowHead(ctx, a.right - 6, ry, 0, 9);
    // Label ABOVE the arrow line so it is not struck through
    ctx.font = '600 13px sans-serif'; ctx.fillStyle = '#222'; ctx.textAlign = 'left'; ctx.textBaseline = 'bottom';
    ctx.fillText('Reaction progress', a.left + 44, ry - 6);

    // dashed reference lines
    ctx.strokeStyle = '#333'; ctx.lineWidth = 1; ctx.setLineDash([5,4]);
    ctx.beginPath(); ctx.moveTo(px(0.12), py(R)); ctx.lineTo(px(0.42), py(R)); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(px(0.30), py(TS)); ctx.lineTo(px(0.62), py(TS)); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(px(0.55), py(P)); ctx.lineTo(px(0.88), py(P)); ctx.stroke();
    ctx.setLineDash([]);

    // double-headed arrows
    ctx.strokeStyle = '#222'; ctx.fillStyle = '#222'; ctx.lineWidth = 1.4;
    var gx1 = px(0.20);
    dblArrow(ctx, gx1, py(R), py(TS));
    haloText(ctx, 'ΔG‡', gx1 - 4, (py(R)+py(TS))/2, 'right');

    var gx2 = px(0.68);
    dblArrow(ctx, gx2, py(R), py(P));
    haloText(ctx, 'ΔG°', gx2 + 6, (py(R)+py(P))/2, 'left');

    ctx.restore();
  }
};

var canvas = document.createElement('canvas');
canvas.style.cssText = 'width:100%;height:100%;display:block';
document.getElementById('container').appendChild(canvas);

var chart = new Chart(canvas, {
  type: 'line',
  data: { datasets: [{
    data: buildData(),
    borderColor: '#e01a83',
    borderWidth: 3,
    pointRadius: 0,
    pointHitRadius: 8,
    tension: 0,
    fill: false
  }]},
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    layout: { padding: { left: 50, right: 18, top: 14, bottom: 44 } },
    scales: {
      x: { type: 'linear', min: 0, max: 1,
           ticks: { display: false }, grid: { display: false }, border: { display: false } },
      y: { type: 'linear', min: 0, max: 1,
           ticks: { display: false }, grid: { display: false }, border: { display: false } }
    },
    plugins: {
      legend: { display: false },
      tooltip: {
        callbacks: {
          title: function(it){ return 'Reaction progress: ' + it[0].parsed.x.toFixed(2); },
          label: function(it){ return 'Energy: ' + it.parsed.y.toFixed(2); }
        }
      }
    }
  },
  plugins: [annotPlugin]
});
window.__markRendered();

function refresh(){
  chart.data.datasets[0].data = buildData();
  chart.update('none');
}

function syncInputs(){
  document.getElementById('barrierHeightInput').value = state.barrier;
  document.getElementById('barrierHeightVal').value = state.barrier.toFixed(2);
  document.getElementById('productEnergyInput').value = state.product;
  document.getElementById('productEnergyVal').value = state.product.toFixed(2);
}

function update_barrierHeight(v){ state.barrier = v; state.preset = null; markPreset(null); refresh(); }
function update_productEnergy(v){ state.product = v; state.preset = null; markPreset(null); refresh(); }

var PRESETS = {
  a: { barrier: 0.55, product: 0.15 },
  b: { barrier: 0.85, product: 0.15 },
  c: { barrier: 0.50, product: 0.45 },
  d: { barrier: 0.90, product: 0.60 }
};
function markPreset(key){
  ['a','b','c','d'].forEach(function(k){
    var el = document.getElementById('preset' + k.toUpperCase());
    if (el) el.classList.toggle('active', k === key);
  });
}
function selectPreset(key){
  state.preset = key;
  state.barrier = PRESETS[key].barrier;
  state.product = PRESETS[key].product;
  markPreset(key); syncInputs(); refresh();
}

// ---- demo step player ----
var steps = [
  { title:'Fast exergonic baseline', narration:'Panel (a): a low barrier (small ΔG‡) means a fast reaction, and products well below reactants (negative ΔG°) means it is exergonic. Both arrows are short-to-moderate.', preset:'a', barrier:0.55, product:0.15 },
  { title:'Raise only the barrier', narration:'Switch to slow exergonic (b): the peak climbs so ΔG‡ grows and the reaction slows, but the product level — and thus ΔG° — is unchanged. Same favorability, different rate.', preset:'b', barrier:0.85, product:0.15 },
  { title:'Flip only the product level', narration:'Switch to fast endergonic (c): the barrier stays shallow (still fast) but the product plateau now sits above the reactants, making ΔG° positive. Rate unchanged, favorability reversed.', preset:'c', barrier:0.50, product:0.45 },
  { title:'Tall barrier AND uphill', narration:'Slow endergonic (d) combines a very tall ΔG‡ with products above reactants: slow and unfavorable. This is the fourth corner of the two-by-two grid.', preset:'d', barrier:0.90, product:0.60 },
  { title:'Explore independence freely', narration:'Now drag the two sliders yourself: move the peak while watching ΔG° stay fixed, then move the product level while ΔG‡ stays fixed. The two arrows respond to different sliders, proving the quantities are independent.', preset:'a', barrier:0.55, product:0.15 }
];
var curStep = 0;
function applyStep(i){
  curStep = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[curStep];
  state.barrier = s.barrier; state.product = s.product; state.preset = s.preset;
  markPreset(s.preset); syncInputs(); refresh();
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (curStep+1) + ' / ' + steps.length;
}
function nextStep(){ applyStep(curStep + 1); }
function prevStep(){ applyStep(curStep - 1); }

applyStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: A reaction's rate is set by its activation barrier (ΔG‡) while its thermodynamic favorability is set by the product–reactant energy difference (ΔG°), and these two quantities vary independently.
KEY INSIGHT (what students should walk away understanding): ΔG‡ (barrier height) governs how fast a reaction goes, while ΔG° (product minus reactant energy) governs whether it is favorable — and you can change one without changing the other.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A reaction's rate is set by its activation barrier (ΔG‡) while its thermodynamic favorability is set by the product–reactant energy difference (ΔG°), and these two quantities vary independently.",
  "figureType": "line_plot",
  "elements": [
    "vertical Energy axis drawn as a tall upward arrow shaded cream-to-orange, labeled 'Energy'",
    "horizontal 'Reaction progress' axis ending in a rightward magenta arrow (no numeric ticks)",
    "pale blue plotting field background",
    "smooth magenta reaction-coordinate curve: flat reactant plateau, single rounded transition-state peak, flat product plateau",
    "dashed horizontal reference line at the reactant energy level",
    "dashed horizontal reference line at the transition-state peak",
    "dashed horizontal reference line at the product energy level",
    "double-headed vertical arrow between reactant line and peak line, labeled 'ΔG‡' (activation barrier)",
    "double-headed vertical arrow between reactant line and product line, labeled 'ΔG°' (overall free-energy change)",
    "panel archetype label (fast/slow × exergonic/endergonic) shown when a preset is selected"
  ],
  "interactions": [
    {
      "id": "profilePreset",
      "type": "toggle",
      "label": "Reaction profile",
      "options": [
        "Fast exergonic (a)",
        "Slow exergonic (b)",
        "Fast endergonic (c)",
        "Slow endergonic (d)"
      ],
      "default": "Fast exergonic (a)",
      "teaches": "The four named archetypes isolate the two independent variables: (a)→(b) raises only the barrier (slower, same ΔG°); (a)→(c) flips only the product level (endergonic, still fast); (d) combines a tall barrier with an uphill step."
    },
    {
      "id": "barrierHeight",
      "type": "slider",
      "label": "Transition-state energy (ΔG‡ peak)",
      "range": [
        0.45,
        0.95,
        0.01
      ],
      "default": 0.55,
      "teaches": "Dragging the peak up or down changes ΔG‡ and therefore the rate, while ΔG° (product minus reactant) stays exactly the same — barrier height controls kinetics, not favorability."
    },
    {
      "id": "productEnergy",
      "type": "slider",
      "label": "Product energy level (ΔG°)",
      "range": [
        0.1,
        0.8,
        0.01
      ],
      "default": 0.15,
      "teaches": "Dragging the product plateau above or below the reactant line changes ΔG° and therefore whether the reaction is exergonic or endergonic, while ΔG‡ (peak minus reactant) is unaffected — favorability is independent of rate."
    }
  ],
  "demo_steps": [
    {
      "title": "Fast exergonic baseline",
      "narration": "Panel (a): a low barrier (small ΔG‡) means a fast reaction, and products well below reactants (negative ΔG°) means it is exergonic. Both arrows are short-to-moderate.",
      "state": {
        "profilePreset": "Fast exergonic (a)",
        "barrierHeight": 0.55,
        "productEnergy": 0.15
      }
    },
    {
      "title": "Raise only the barrier",
      "narration": "Switch to slow exergonic (b): the peak climbs so ΔG‡ grows and the reaction slows, but the product level — and thus ΔG° — is unchanged. Same favorability, different rate.",
      "state": {
        "profilePreset": "Slow exergonic (b)",
        "barrierHeight": 0.85,
        "productEnergy": 0.2
      }
    },
    {
      "title": "Flip only the product level",
      "narration": "Switch to fast endergonic (c): the barrier stays shallow (still fast) but the product plateau now sits above the reactants, making ΔG° positive. Rate unchanged, favorability reversed.",
      "state": {
        "profilePreset": "Fast endergonic (c)",
        "barrierHeight": 0.5,
        "productEnergy": 0.45
      }
    },
    {
      "title": "Tall barrier AND uphill",
      "narration": "Slow endergonic (d) combines a very tall ΔG‡ with products above reactants: slow and unfavorable. This is the fourth corner of the two-by-two grid.",
      "state": {
        "profilePreset": "Slow endergonic (d)",
        "barrierHeight": 0.9,
        "productEnergy": 0.6
      }
    },
    {
      "title": "Explore independence freely",
      "narration": "Now drag the two sliders yourself: move the peak while watching ΔG° stay fixed, then move the product level while ΔG‡ stays fixed. The two arrows respond to different sliders, proving the quantities are independent.",
      "state": {
        "profilePreset": "Fast exergonic (a)",
        "barrierHeight": 0.55,
        "productEnergy": 0.15
      }
    }
  ],
  "keyInsight": "ΔG‡ (barrier height) governs how fast a reaction goes, while ΔG° (product minus reactant energy) governs whether it is favorable — and you can change one without changing the other.",
  "reconstructionNotes": "Render a single enlarged reaction-coordinate plot (the toggle selects which archetype is shown, rather than a 2x2 grid). Vertical Energy axis as a cream-to-orange gradient up-arrow on the left; horizontal 'Reaction progress' axis as a magenta right-arrow at the bottom; pale blue plot background; no numeric ticks. The magenta curve is a smooth spline through a flat reactant plateau (fixed baseline ~0.4), a single rounded peak at the barrierHeight value, and a flat product plateau at the productEnergy value. Draw three thin black dashed horizontal lines at reactant, peak, and product levels. Draw a double-headed vertical arrow from reactant line to peak line labeled 'ΔG‡' and another from reactant line to product line labeled 'ΔG°'; recompute and reposition both arrows and the dashed lines live as the sliders move. Use the ‡ and ° symbols in the labels. Keep the curve magenta/pink to match the source figure."
}

