// @FIGURE_CODE_BEGIN
var R_LEVEL = 0.4; // fixed reactant baseline
var state = { barrier: 0.55, product: 0.15, preset: 'a' };

function smoothstep(u){ u = Math.max(0, Math.min(1, u)); return u*u*(3-2*u); }

// Asymmetric curve: steep rise, gradual descent
var PEAK_POS = 0.38;
var SIGMA_LEFT = 0.065;   // narrow → steep rise
var SIGMA_RIGHT = 0.14;   // wide → gradual descent

function curvePoint(t){
  var R = R_LEVEL, TS = state.barrier, P = state.product;
  // Asymmetric baseline: rise is shorter, descent is longer
  var base;
  if (t <= PEAK_POS) {
    base = R + (TS - R) * smoothstep((t - 0.10) / (PEAK_POS - 0.10)) * 0.35;
  } else {
    base = P + (TS - P) * smoothstep((0.85 - t) / (0.85 - PEAK_POS)) * 0.35;
  }
  // Asymmetric Gaussian bump
  var sig = (t <= PEAK_POS) ? SIGMA_LEFT : SIGMA_RIGHT;
  var g = Math.exp(-((t - PEAK_POS) * (t - PEAK_POS)) / (2 * sig * sig));
  // Amplitude so curve(PEAK_POS) = TS
  var baseAtPeak = R + (TS - R) * 0.35; // smoothstep(1)=1 at peak from left
  var A = TS - baseAtPeak;
  return base + A * g;
}

function buildData(){
  var pts = [];
  for (var i = 0; i <= 400; i++){
    var t = i / 400;
    pts.push({ x: t, y: curvePoint(t) });
  }
  return pts;
}

function arrowHead(ctx, x, y, ang, s){
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x - s*Math.cos(ang - 0.42), y - s*Math.sin(ang - 0.42));
  ctx.lineTo(x - s*Math.cos(ang + 0.42), y - s*Math.sin(ang + 0.42));
  ctx.closePath();
  ctx.fill();
}

function dblArrow(ctx, x, y1, y2){
  ctx.beginPath(); ctx.moveTo(x, y1); ctx.lineTo(x, y2); ctx.stroke();
  var up = (y1 < y2) ? -Math.PI/2 : Math.PI/2;
  var dn = (y1 < y2) ? Math.PI/2 : -Math.PI/2;
  arrowHead(ctx, x, y1, up, 7);
  arrowHead(ctx, x, y2, dn, 7);
}

function haloText(ctx, txt, x, y, align){
  ctx.save();
  ctx.font = '600 13px sans-serif';
  ctx.textAlign = align || 'center';
  ctx.textBaseline = 'middle';
  ctx.lineWidth = 4; ctx.strokeStyle = '#ffffff'; ctx.lineJoin = 'round';
  ctx.strokeText(txt, x, y);
  ctx.fillStyle = '#111';
  ctx.fillText(txt, x, y);
  ctx.restore();
}

var PANEL_LABELS = { a: '(a)', b: '(b)', c: '(c)', d: '(d)' };

var annotPlugin = {
  id: 'annot',
  beforeDraw: function(chart){
